import { useTranslation } from "react-i18next";
import { useSearchParams } from "react-router";
import { KnowledgeView } from "~/knowledge/KnowledgeView";
import type { KnowledgeBundle } from "~/knowledge/types";
import { useHydrated } from "~/shell/useHydrated";
import bundle from "../../public/knowledge/bundle.json";
import type { Route } from "./+types/knowledge";

export const meta: Route.MetaFunction = () => [{ title: "Knowledge · PitStudio" }];

// The bundle is generated by `tools/build_knowledge.py` (FR-020-32) and committed; the page prerenders from it.
export default function KnowledgePage() {
  const { t } = useTranslation("app");
  const { t: tResults } = useTranslation("results");
  const [params] = useSearchParams();
  const hydrated = useHydrated();
  return (
    <article>
      <h1>{t("pages.knowledge.title")}</h1>
      <p>{tResults("knowledge.lead")}</p>
      <KnowledgeView
        bundle={bundle as unknown as KnowledgeBundle}
        section={hydrated ? (params.get("section") ?? undefined) : undefined}
      />
    </article>
  );
}
